/* ============ FASE 2 · ÁREA C: INVESTIGACIÓN DE OPERACIONES (contenido por bloques de la plantilla) ============
   Cada tema: def, con, fx [[título, tex, alternativa, variables, por qué funciona]], met, ejB, ejA (uno o más), err, ejer [enunciado, pista1, pista2, solución], fic.
   Todos los números fueron verificados con cálculo independiente y con la calculadora de la app. Las empresas y cifras de los ejemplos son ilustrativas. */
const T2 = {};
const ilus = '<p class="hint">Datos ilustrativos: la empresa y las cifras son de ejemplo, construidas para practicar; no son estadísticas oficiales.</p>';
const q9ol = a => '<ol class="deep-steps">' + a.map(x => "<li>" + x + "</li>").join("") + "</ol>";
const q9ul = a => "<ul>" + a.map(x => "<li>" + x + "</li>").join("") + "</ul>";
const q9dl = a => '<dl class="deep-dl">' + a.map(x => "<dt>" + x[0] + "</dt><dd>" + x[1] + "</dd>").join("") + "</dl>";
const q9bx = (t, h) => '<div class="deep-b"><h4>' + t + "</h4>" + h + "</div>";

/* ---------------- PROGRAMACIÓN LINEAL ---------------- */
T2["programacion-lineal"] = {
  def:"<p><b>Programación lineal (PL)</b> es un método para elegir los valores de varias decisiones (cuánto producir, comprar o enviar) que hacen <b>máximo</b> un beneficio o <b>mínimo</b> un costo, respetando límites de recursos. Se llama «lineal» porque tanto el objetivo como las restricciones son sumas de términos del tipo coeficiente × variable: no hay potencias, productos entre variables ni divisiones por variables.</p><p>Todo modelo de PL tiene tres partes: <b>variables de decisión</b> (lo que eliges), <b>función objetivo</b> (lo que quieres maximizar o minimizar) y <b>restricciones</b> (lo que te limita), más la condición de que las variables no sean negativas.</p>",
  con:q9dl([["Región factible", "Conjunto de todas las combinaciones que cumplen todas las restricciones. En 2 variables es un polígono; en más variables, un poliedro."], ["Vértice (solución básica)", "Esquina de la región factible. Si el problema tiene óptimo, al menos un vértice es óptimo."], ["Restricción activa", "Se cumple con igualdad en el óptimo: ese recurso se usa completo (holgura 0). Es un cuello de botella."], ["Holgura / excedente", "Lo que sobra de un recurso (≤) o lo que se supera un mínimo (≥)."], ["Simplex", "Algoritmo que salta de vértice en vértice vecino, siempre mejorando el objetivo, hasta que ningún vecino mejora."], ["Dual", "Otro modelo, construido con los mismos datos, cuyas variables son los «precios» de los recursos. Su óptimo vale lo mismo que el del primal."], ["Precio sombra", "Cuánto mejora el objetivo si aumenta en una unidad el lado derecho de una restricción, mientras la base óptima no cambie."], ["Análisis de sensibilidad", "Estudia cuánto pueden cambiar un coeficiente o un recurso sin que cambie la solución óptima (o la base)."]]),
  fx:[["Modelo general", "\\max\\ Z=\\sum_{j=1}^{n} c_j x_j \\quad \\text{s.a.}\\quad \\sum_{j=1}^{n} a_{ij}x_j\\le b_i,\\quad x_j\\ge 0", "Máx Z = Σ c_j·x_j   s.a.   Σ a_ij·x_j ≤ b_i ,  x_j ≥ 0", [["x_j", "cantidad de la actividad j (variable de decisión)"], ["c_j", "aporte de una unidad de j al objetivo"], ["a_ij", "recurso i que consume una unidad de j"], ["b_i", "disponibilidad del recurso i"]], "<p>Si una unidad aporta c_j, entonces x_j unidades aportan c_j·x_j (proporcionalidad), y los aportes de distintos productos se suman (aditividad). Con esos dos supuestos todo el modelo queda como sumas lineales, y entonces la región factible es convexa y el óptimo está en un vértice.</p>"],
      ["Dual de un problema de máximo", "\\min\\ W=\\sum_i b_i y_i \\quad\\text{s.a.}\\quad \\sum_i a_{ij} y_i \\ge c_j,\\quad y_i\\ge 0", "Mín W = Σ b_i·y_i   s.a.   Σ a_ij·y_i ≥ c_j ,  y_i ≥ 0", [["y_i", "valor (precio sombra) de una unidad del recurso i"]], "<p>Imagina que alguien quiere comprarte todos tus recursos. Para que aceptes vender, el precio pagado por los recursos que consume una unidad de cada producto debe ser al menos lo que esa unidad te deja (Σ a_ij·y_i ≥ c_j). El comprador busca pagar lo mínimo (Mín W). El teorema de dualidad fuerte asegura que ese mínimo es exactamente tu máximo: W* = Z*.</p>"],
      ["Rango de optimalidad (2 variables)", "\\text{pendiente de la restricción 1}\\ \\le\\ \\frac{c_1}{c_2}\\ \\le\\ \\text{pendiente de la restricción 2}", "pendiente restricción 1 ≤ c₁ ÷ c₂ ≤ pendiente restricción 2", [["c₁/c₂", "razón entre los aportes de los productos"]], "<p>En el gráfico, la recta del objetivo «rueda» al cambiar c₁. Mientras su inclinación quede entre las inclinaciones de las dos restricciones activas, el mismo vértice sigue siendo el último que toca la recta al desplazarla, y por lo tanto sigue siendo óptimo.</p>"]],
  met:q9ol(["<b>Define las variables</b> con unidades y período: «x₁ = cajas de cereza premium por día».", "<b>Escribe el objetivo</b>: aporte unitario × variable, sumado.", "<b>Escribe una restricción por recurso o regla</b>: lo que se usa ≤ lo disponible; mínimos con ≥. Revisa que ambos lados tengan la misma unidad.", "<b>Agrega la no negatividad</b> (x ≥ 0) y decide si las variables deben ser enteras.", "<b>Resuelve:</b> con 2 variables, por el método gráfico (dibuja, encuentra los vértices, evalúa Z en cada uno); con más variables, con Simplex (calculadora de la app, Solver de Excel o LINGO).", "<b>Simplex a mano:</b> agrega holguras, arma la tabla, elige como variable que entra la de coeficiente más negativo en la fila Z, elige la que sale con la menor razón lado derecho ÷ coeficiente positivo, pivotea y repite hasta que la fila Z no tenga negativos.", "<b>Interpreta:</b> valores de x, valor de Z, restricciones activas, holguras y precios sombra.", "<b>Sensibiliza:</b> ¿hasta dónde puede cambiar un precio o un recurso sin cambiar la decisión?"]) +
    q9bx("Simplex paso a paso con el ejemplo básico", "<p>Forma estándar: 2x₁ + x₂ + s₁ = 100; x₁ + x₂ + s₂ = 80; x₁ + s₃ = 40; fila Z: Z − 8x₁ − 5x₂ = 0.</p>" +
      table(["Iteración", "Entra", "Sale (razón mínima)", "Z", "Solución"], [["Inicio", "—", "—", "0", "x₁ = 0, x₂ = 0"], ["1", "x₁ (−8 es el más negativo)", "s₃: razones 100÷2 = 50, 80÷1 = 80, 40÷1 = 40 → 40", "320", "x₁ = 40, x₂ = 0"], ["2", "x₂ (−5)", "s₁: razones 20÷1 = 20, 40÷1 = 40 → 20", "420", "x₁ = 40, x₂ = 20"], ["3", "s₃ (−2)", "s₂: razones 20÷1 = 20, 40÷1 = 40 → 20", "460", "x₁ = 20, x₂ = 60"]]) +
      "<p>En la tabla final la fila Z queda 0 · 0 · 3 · 2 · 0 | 460: no hay negativos, así que es óptimo. Los coeficientes de s₁ y s₂ en la fila Z (3 y 2) son los <b>precios sombra</b> de selección y embalaje.</p>"),
  ejB:["Packing de cerezas en la Región de O'Higgins (método gráfico)", ilus + "<p>Un packing arma cajas <b>premium</b> (x₁) y <b>estándar</b> (x₂). Cada caja premium deja $8 mil y la estándar $5 mil. Por día hay 100 horas-persona de selección (premium usa 2 h/caja, estándar 1 h), 80 horas de embalaje (1 h cada una) y el cupo de carga aérea permite como máximo 40 cajas premium.</p>" +
    TX("\\max Z=8x_1+5x_2\\quad \\text{s.a.}\\ 2x_1+x_2\\le 100,\\ x_1+x_2\\le 80,\\ x_1\\le 40,\\ x_1,x_2\\ge 0", "Máx Z = 8x₁ + 5x₂   s.a.  2x₁ + x₂ ≤ 100 ;  x₁ + x₂ ≤ 80 ;  x₁ ≤ 40", true) +
    q9ol(["Se dibujan las tres rectas (2x₁ + x₂ = 100 corta los ejes en (50, 0) y (0, 100); x₁ + x₂ = 80 en (80, 0) y (0, 80); x₁ = 40 es vertical).", "La región factible es el polígono con vértices (0, 0), (40, 0), (40, 20), (20, 60) y (0, 80).", "El vértice (20, 60) sale de resolver 2x₁ + x₂ = 100 y x₁ + x₂ = 80: restando, x₁ = 20, y luego x₂ = 60.", "Se evalúa Z en cada vértice:"]) +
    table(["Vértice", "Z = 8x₁ + 5x₂"], [["(0, 0)", "0"], ["(40, 0)", "320"], ["(40, 20)", "420"], ["(20, 60)", "<b>460</b>"], ["(0, 80)", "400"]]) +
    "<p><b>Decisión:</b> 20 cajas premium y 60 estándar por día, utilidad $460 mil. Selección y embalaje quedan completos (activas); del cupo aéreo sobran 20 cajas. Comprobado con la calculadora de la app.</p>"],
  ejA:[["Dualidad y sensibilidad del packing", "<p><b>Dual.</b> Con y₁, y₂, y₃ = valor de una hora de selección, una hora de embalaje y un cupo aéreo:</p>" + TX("\\min W=100y_1+80y_2+40y_3\\quad\\text{s.a.}\\ 2y_1+y_2+y_3\\ge 8,\\ y_1+y_2\\ge 5", "Mín W = 100y₁ + 80y₂ + 40y₃   s.a.  2y₁ + y₂ + y₃ ≥ 8 ;  y₁ + y₂ ≥ 5", true) +
      "<p>Como el cupo aéreo sobra, su precio es y₃ = 0. Las otras dos restricciones del dual quedan con igualdad: 2y₁ + y₂ = 8 y y₁ + y₂ = 5 → <b>y₁ = 3</b>, <b>y₂ = 2</b>. Entonces W = 100·3 + 80·2 = 460 = Z: se cumple la dualidad fuerte.</p>" +
      "<p><b>Lectura:</b> una hora extra de selección vale hasta $3 mil y una de embalaje hasta $2 mil. Si contratar una hora extra de selección cuesta $2.500, conviene; si cuesta $3.500, no.</p>" +
      "<p><b>Rango del precio sombra de selección.</b> Con b₁ horas de selección, el vértice óptimo es x₁ = b₁ − 80 y x₂ = 160 − b₁. Sigue siendo válido mientras x₁ ≥ 0 y x₁ ≤ 40, es decir, <b>80 ≤ b₁ ≤ 120</b>. Fuera de ese rango cambian las restricciones activas y el precio sombra de 3 deja de valer.</p>" +
      "<p><b>Rango de optimalidad de la caja premium.</b> Las restricciones activas tienen pendientes 2 (selección) y 1 (embalaje). El vértice (20, 60) sigue óptimo mientras 1 ≤ c₁ ÷ 5 ≤ 2, o sea <b>$5 mil ≤ c₁ ≤ $10 mil</b>. Verificado: con c₁ = 10,1 el óptimo salta a (40, 20); con c₁ = 4,9, a (0, 80).</p>"],
    ["Mezcla de mineral en una faena del norte (3 variables)", ilus + "<p>Una planta concentradora necesita 10.000 t/día de mineral con ley media de cobre de al menos 0,87 % y dureza media de a lo más 12,5 (índice). Puede extraer de tres frentes:</p>" +
      table(["Frente", "Ley Cu (%)", "Dureza (índice)", "Costo (USD/t)", "Máximo (t/día)"], [["A", "1,2", "14", "9", "4.000"], ["B", "0,6", "10", "5", "6.000"], ["C", "0,9", "12", "7", "5.000"]], { num:[1, 2, 3, 4] }) +
      TX("\\min Z=9A+5B+7C\\quad\\text{s.a.}\\ A+B+C=10000,\\ 1{,}2A+0{,}6B+0{,}9C\\ge 8700,\\ 14A+10B+12C\\le 125000", "Mín Z = 9A + 5B + 7C   s.a.  A + B + C = 10000 ;  1,2A + 0,6B + 0,9C ≥ 8700 ;  14A + 10B + 12C ≤ 125000", true) +
      "<p>La ley media es (1,2A + 0,6B + 0,9C) ÷ 10.000 ≥ 0,87 %; multiplicando por 10.000 queda lineal (≥ 8.700). Lo mismo con la dureza (≤ 125.000). Se agregan A ≤ 4.000, B ≤ 6.000 y C ≤ 5.000.</p>" +
      "<p><b>Óptimo:</b> A = 4.000 t, B = 5.000 t, C = 1.000 t; costo <b>USD 68.000 por día</b>. Activas: total, ley mínima y el máximo de A. La dureza queda en 118.000 ÷ 10.000 = 11,8 (bajo 12,5).</p>" +
      "<p><b>Sensibilidad:</b> subir la ley exigida a 0,88 % (lado derecho 8.800) eleva el costo a USD 68.666,67: el precio sombra de la ley es USD 6,67 por cada unidad de «tonelada·%». Cada 0,01 punto de ley adicional cuesta unos USD 667 por día.</p>"]],
  err:q9ul(["Mezclar unidades: tiempos en minutos y capacidad en horas.", "Escribir la ley media como cociente (… ÷ total ≥ 0,87): no es lineal. Multiplica por el total.", "Olvidar restricciones obvias (demanda máxima, capacidad de bodega) y obtener soluciones absurdas o «no acotadas».", "Redondear una solución fraccionaria cuando las variables deben ser enteras: puede quedar infactible. Usa variables enteras.", "Usar un precio sombra fuera de su rango de validez.", "Confundir holgura (lo que sobra) con precio sombra (lo que vale una unidad más)."]),
  ejer:["<p>Un taller confecciona chaquetas (x) y pantalones (y) de trabajo. Utilidad: $3 mil por chaqueta y $2 mil por pantalón. Restricciones diarias: x + y ≤ 4 (horas de corte), x + 3y ≤ 6 (horas de costura), x ≤ 3 (tela especial). ¿Cuánto fabricar?</p>", "Dibuja las tres rectas y marca la región que cumple todas. ¿Cuáles son sus esquinas?", "Los vértices son (0, 0), (3, 0), (3, 1) y (0, 2). Evalúa Z = 3x + 2y en cada uno.", "<p>Z(0, 0) = 0; Z(3, 0) = 9; <b>Z(3, 1) = 11</b>; Z(0, 2) = 4. Óptimo: 3 chaquetas y 1 pantalón, $11 mil. En (3, 1) se cumplen con igualdad las tres restricciones (3 + 1 = 4; 3 + 3 = 6; x = 3).</p>"],
  fic:["Tres partes: variables, objetivo y restricciones (más x ≥ 0).", "El óptimo está en un vértice de la región factible.", "Simplex: entra el más negativo de la fila Z; sale la menor razón positiva.", "Precio sombra = valor de una unidad más de recurso, válido en su rango.", "Dual: mismo valor óptimo que el primal (W* = Z*).", "Si las variables son unidades completas, usa programación entera."]
};

/* ---------------- TRANSPORTE ---------------- */
T2["transporte"] = {
  def:"<p>El <b>problema de transporte</b> decide cuántas unidades enviar desde cada <b>origen</b> (plantas, bodegas, puertos) a cada <b>destino</b> (clientes, tiendas) para atender la demanda al <b>menor costo total</b>, sin superar la oferta de cada origen. Es un caso especial de programación lineal con una estructura que permite resolverlo con métodos más simples.</p>",
  con:q9dl([["Oferta (aᵢ)", "Unidades disponibles en el origen i."], ["Demanda (bⱼ)", "Unidades requeridas por el destino j."], ["Problema balanceado", "Oferta total = demanda total. Si no, se agrega un origen o destino ficticio con costo 0."], ["Solución básica", "Una asignación con a lo más m + n − 1 rutas usadas (m orígenes, n destinos)."], ["Esquina noroeste", "Método inicial rápido que ignora los costos."], ["Vogel (VAM)", "Método inicial que usa penalizaciones (diferencia entre los dos costos más bajos de cada fila y columna); suele quedar en o muy cerca del óptimo."], ["MODI (u-v)", "Prueba de optimalidad: calcula el costo reducido de cada ruta no usada; si ninguno es negativo, la solución es óptima."]]),
  fx:[["Modelo", "\\min Z=\\sum_i\\sum_j c_{ij}x_{ij}\\quad\\text{s.a.}\\ \\sum_j x_{ij}\\le a_i,\\ \\sum_i x_{ij}=b_j,\\ x_{ij}\\ge 0", "Mín Z = Σ Σ c_ij·x_ij   s.a.  Σ_j x_ij ≤ a_i ;  Σ_i x_ij = b_j", [["x_ij", "unidades enviadas de i a j"], ["c_ij", "costo por unidad de la ruta i → j"]], "<p>Cada unidad enviada por una ruta cuesta c_ij, así que el costo total es la suma de costo × cantidad en todas las rutas. Las restricciones obligan a no sacar de un origen más de lo que tiene y a entregar a cada destino exactamente lo que pide.</p>"],
      ["Costo reducido (MODI)", "d_{ij}=c_{ij}-(u_i+v_j)", "d_ij = c_ij − (u_i + v_j)", [["u_i, v_j", "se obtienen de las rutas usadas: c_ij = u_i + v_j, partiendo de u₁ = 0"]], "<p>u_i + v_j es lo que «cuesta implícitamente» llevar una unidad de i a j a través de las rutas que ya se usan. Si una ruta directa cuesta menos que eso (d_ij &lt; 0), mover unidades a esa ruta baja el costo total, así que la solución aún no es óptima.</p>"]],
  met:q9ol(["Arma la tabla de costos (orígenes en filas, destinos en columnas) y anota oferta y demanda.", "Balancea: si sobra oferta, agrega un destino ficticio con costo 0 (lo enviado ahí es lo que no se despacha); si falta, agrega un origen ficticio (demanda no atendida).", "Obtén una solución inicial: esquina noroeste (rápida) o Vogel (mejor).", "Vogel: calcula para cada fila y columna la diferencia entre sus dos costos más bajos; en la fila o columna con mayor penalización, asigna lo máximo posible a la celda más barata; tacha lo agotado y repite.", "Verifica que haya m + n − 1 rutas básicas.", "Prueba MODI: con u₁ = 0, despeja u y v en las rutas usadas; calcula d_ij en las no usadas. Si todos los d_ij ≥ 0, es óptima.", "Si algún d_ij &lt; 0, haz un ciclo de reasignación (stepping stone) por esa ruta y repite."]),
  ejB:["Distribuidora de agua embotellada en la zona central", ilus + "<p>Dos plantas, Santiago (250 pallets) y Rancagua (150), abastecen a Talca (120), Curicó (130) y San Fernando (150). Costo por pallet en miles de $:</p>" +
    table(["Origen \\ Destino", "Talca", "Curicó", "San Fernando", "Oferta"], [["Santiago", "8", "6", "4", "250"], ["Rancagua", "5", "4", "3", "150"], ["Demanda", "120", "130", "150", "400"]], { num:[1, 2, 3, 4] }) +
    "<p><b>Esquina noroeste:</b> Santiago→Talca 120, Santiago→Curicó 130, Rancagua→San Fernando 150. Costo = 960 + 780 + 450 = <b>2.190</b>.</p>" +
    "<p><b>Vogel:</b></p>" + q9ol(["Penalizaciones: filas 2 (Santiago: 6 − 4) y 1 (Rancagua: 4 − 3); columnas 3 (Talca: 8 − 5), 2 y 1. La mayor es Talca → su celda más barata es Rancagua (5): se asignan 120. Rancagua queda con 30.", "Nuevas penalizaciones: Santiago 2, Rancagua 1, Curicó 2, San Fernando 1. Empate en 2; se elige la fila Santiago → su celda más barata es San Fernando (4): 150.", "Queda solo Curicó (130): Santiago 100 y Rancagua 30."]) +
    "<p>Costo Vogel = 120·5 + 150·4 + 100·6 + 30·4 = <b>1.920</b>.</p><p><b>MODI:</b> u_Stgo = 0 → v_Curicó = 6, v_SanF = 4; u_Rcg = 4 − 6 = −2; v_Talca = 5 + 2 = 7. Rutas no usadas: Santiago→Talca: 8 − 7 = 1; Rancagua→San Fernando: 3 − 2 = 1. Ninguno negativo → <b>1.920 es óptimo</b> (comprobado con la calculadora). El noroeste costaba 14 % más.</p>"],
  ejA:["Distribución desde ZOFRI con oferta mayor que la demanda", ilus + "<p>Un importador tiene 500 unidades en una bodega en ZOFRI (Iquique) y 400 en Antofagasta. Sus tiendas piden: Arica 250, Calama 300 y Copiapó 200 (total 750). Costo por unidad en miles de $:</p>" +
    table(["Origen \\ Destino", "Arica", "Calama", "Copiapó", "Ficticio", "Oferta"], [["ZOFRI Iquique", "4", "7", "12", "0", "500"], ["Antofagasta", "9", "3", "6", "0", "400"], ["Demanda", "250", "300", "200", "150", "900"]], { num:[1, 2, 3, 4, 5] }) +
    "<p>Como sobran 900 − 750 = 150 unidades, se agrega un destino ficticio con costo 0.</p>" +
    "<p><b>Vogel:</b> la mayor penalización inicial es Copiapó (12 − 6 = 6) → Antofagasta→Copiapó 200. Luego Arica (9 − 4 = 5) → ZOFRI→Arica 250. Después la fila ZOFRI (7 − 0 = 7) → ZOFRI→Ficticio 150; nuevamente ZOFRI (7) → ZOFRI→Calama 100; y Antofagasta→Calama 200.</p>" +
    "<p>Costo = 250·4 + 100·7 + 200·3 + 200·6 = <b>3.500</b> (el noroeste da 4.100).</p><p><b>MODI:</b> u_ZOFRI = 0 → v_Arica = 4, v_Calama = 7, v_Ficticio = 0; u_Antof = 3 − 7 = −4 → v_Copiapó = 10. Rutas no usadas: ZOFRI→Copiapó 12 − 10 = 2; Antof→Arica 9 − 0 = 9; Antof→Ficticio 0 + 4 = 4. Todos ≥ 0 → óptimo.</p><p><b>Lectura:</b> las 150 unidades que no se despachan quedan en ZOFRI, porque Iquique está lejos de Calama y Copiapó; Antofagasta se vacía completa.</p>"],
  err:q9ul(["No balancear antes de aplicar Vogel o MODI.", "Dar al ficticio un costo distinto de 0 (salvo que exista un costo real de bodegaje o de demanda no atendida).", "Quedar con menos de m + n − 1 rutas básicas (degeneración): agrega un cero en una celda que no forme ciclo.", "Creer que Vogel siempre da el óptimo: hay que verificar con MODI.", "Usar costos por viaje cuando las cantidades están en unidades (o al revés)."]),
  ejer:["<p>Dos bodegas (A: 60, B: 40) abastecen dos clientes (1: 50, 2: 50). Costos: A→1 = 3, A→2 = 5, B→1 = 4, B→2 = 2. Encuentra el plan de mínimo costo.</p>", "El problema está balanceado (100 = 100). Mira qué bodega es más barata para cada cliente.", "A es la más barata para el cliente 1 y B para el 2. Asigna lo máximo a esas rutas y completa con lo que falte.", "<p>A→1 = 50, B→2 = 40 y, como al cliente 2 le faltan 10, A→2 = 10. Costo = 150 + 80 + 50 = <b>280</b>. MODI: u_A = 0, v₁ = 3, v₂ = 5, u_B = −3; ruta B→1: 4 − (−3 + 3) = 4 ≥ 0 → óptimo.</p>"],
  fic:["Balancea con un ficticio de costo 0.", "Inicial: noroeste (rápido) o Vogel (bueno).", "Óptimo si todos los costos reducidos d_ij = c_ij − (u_i + v_j) ≥ 0.", "m + n − 1 rutas básicas.", "Lo enviado al ficticio es lo que no se despacha (o la demanda no atendida)."]
};

/* ---------------- ASIGNACIÓN ---------------- */
T2["asignacion"] = {
  def:"<p>El <b>problema de asignación</b> empareja recursos (personas, máquinas, grúas) con tareas, uno a uno, para minimizar el costo o tiempo total, o maximizar el rendimiento total. Es un problema de transporte en que cada oferta y cada demanda valen 1. Se resuelve con el <b>método húngaro</b>.</p>",
  con:q9dl([["Matriz cuadrada", "Igual número de filas (recursos) y columnas (tareas). Si no, se agregan filas o columnas ficticias con ceros."], ["Reducción", "Restar el mínimo de cada fila y luego de cada columna no cambia la asignación óptima y crea ceros."], ["Cubrir ceros", "Si con menos de n líneas se cubren todos los ceros, aún no hay asignación completa."], ["Maximización", "Se convierte restando cada valor del mayor de la matriz (costo de oportunidad)."], ["Asignación prohibida", "Se le pone un costo muy grande M para que nunca se elija."]]),
  fx:[["Modelo", "\\min Z=\\sum_i\\sum_j c_{ij}x_{ij}\\quad\\text{s.a.}\\ \\sum_j x_{ij}=1,\\ \\sum_i x_{ij}=1,\\ x_{ij}\\in\\{0,1\\}", "Mín Z = Σ Σ c_ij·x_ij   s.a.  Σ_j x_ij = 1 ;  Σ_i x_ij = 1", [["x_ij", "1 si el recurso i hace la tarea j; 0 si no"]], "<p><b>Por qué funciona la reducción:</b> si restas k a toda una fila, cualquier asignación completa usa exactamente una celda de esa fila, así que todas las asignaciones bajan en k: el orden entre ellas no cambia. Cuando encuentras una asignación completa solo con ceros, su costo reducido es 0, el mínimo posible, por lo que es óptima.</p>"]],
  met:q9ol(["Arma la matriz cuadrada (agrega ficticios con 0 si hace falta). Si es de máximo, convierte: c′ = máximo − c. Pon M en las asignaciones imposibles.", "Resta el mínimo de cada fila.", "Resta el mínimo de cada columna.", "Busca una asignación con un cero por fila y columna. Si existe, terminaste.", "Si no, cubre todos los ceros con el menor número de líneas.", "Toma el menor valor no cubierto: réstalo a los no cubiertos y súmalo a los que están en el cruce de dos líneas. Vuelve al paso 4.", "Calcula el total con los valores <b>originales</b>."]),
  ejB:["Tres operarios y tres tareas en una maestranza", ilus + "<p>Minutos que tarda cada operario en cada tarea:</p>" + table(["", "Cortar", "Soldar", "Pintar"], [["Ana", "10", "7", "8"], ["Benjamín", "5", "9", "6"], ["Camila", "8", "6", "11"]], { num:[1, 2, 3] }) +
    q9ol(["Mínimos de fila: 7, 5 y 6. Quedan las filas (3, 0, 1), (0, 4, 1) y (2, 0, 5).", "Mínimos de columna: 0, 0 y 1. Quedan (3, 0, 0), (0, 4, 0) y (2, 0, 4).", "Camila solo tiene cero en Soldar → Camila-Soldar. Ana, entonces, Pintar; Benjamín, Cortar."]) +
    "<p>Total con valores originales: 8 + 5 + 6 = <b>19 minutos</b>. Revisando las 6 combinaciones posibles, ninguna es menor.</p>"],
  ejA:["Grúas a naves en un terminal portuario (máximo, con una asignación prohibida)", ilus + "<p>Movimientos por hora que logra cada grúa con cada nave; la grúa 1 no alcanza la nave 4 (prohibida):</p>" + table(["", "Nave 1", "Nave 2", "Nave 3", "Nave 4"], [["Grúa 1", "26", "29", "23", "—"], ["Grúa 2", "25", "30", "20", "24"], ["Grúa 3", "29", "30", "31", "22"], ["Grúa 4", "31", "25", "28", "29"]], { num:[1, 2, 3, 4] }) +
    q9ol(["Convertir a mínimo restando del mayor (31). La celda prohibida recibe M: G1 (5, 2, 8, M); G2 (6, 1, 11, 7); G3 (2, 1, 0, 9); G4 (0, 6, 3, 2).", "Reducción de filas (2, 1, 0, 0) y luego de columnas (solo la columna 4 tiene mínimo 2): G1 (3, 0, 6, M); G2 (5, 0, 10, 4); G3 (2, 1, 0, 7); G4 (0, 6, 3, 0).", "G1 y G2 tienen cero solo en la nave 2: no hay asignación completa. Los ceros se cubren con 3 líneas (columna 2, columna 3 y fila G4).", "Menor no cubierto = 2. Se resta a los no cubiertos y se suma a los cruces: G1 (1, 0, 6, M); G2 (3, 0, 10, 2); G3 (0, 1, 0, 5); G4 (0, 8, 5, 0).", "Todavía G1 y G2 compiten por la nave 2. Nuevas 3 líneas (columna 2, filas G3 y G4); menor no cubierto = 1: G1 (0, 0, 5, M); G2 (2, 0, 9, 1); G3 (0, 2, 0, 5); G4 (0, 9, 5, 0).", "Asignación con ceros: G2→Nave 2, G1→Nave 1, G3→Nave 3, G4→Nave 4."]) +
    "<p>Total con valores originales: 26 + 30 + 31 + 29 = <b>116 movimientos/hora</b>. Es el máximo de las 24 combinaciones; la segunda mejor da 115.</p>"],
  err:q9ul(["Sumar los valores de la matriz reducida en vez de los originales.", "Olvidar convertir un problema de máximo.", "Dejar la matriz rectangular.", "Poner 0 en vez de M en una asignación imposible.", "Cubrir los ceros con más líneas de las necesarias y concluir mal."]),
  ejer:["<p>Asigna tres camiones (1, 2, 3) a tres rutas (A, B, C) con estos costos (miles de $): camión 1: 9, 11, 14; camión 2: 6, 15, 13; camión 3: 12, 13, 6.</p>", "Resta el mínimo de cada fila: 9, 6 y 6.", "Después resta el mínimo de cada columna. Busca un cero por fila y columna: el camión 2 tiene un solo cero.", "<p>Matriz reducida: (0, 0, 5), (0, 7, 7), (6, 5, 0). Camión 2→A, camión 3→C y camión 1→B. Costo: 11 + 6 + 6 = <b>23</b> (mínimo de las 6 combinaciones).</p>"],
  fic:["Matriz cuadrada; ficticios con 0.", "Máximo → restar del mayor.", "Reducir filas y columnas.", "Menos de n líneas → ajustar con el menor no cubierto.", "Sumar con los valores originales."]
};

/* ---------------- REDES: RUTA MÁS CORTA Y ÁRBOL DE EXPANSIÓN ---------------- */
T2["ruta-corta"] = {
  def:"<p>Una <b>red</b> (grafo) es un conjunto de <b>nodos</b> (lugares) unidos por <b>arcos</b> (caminos, cañerías, cables) con un valor: distancia, tiempo o costo. Los problemas de redes más usados son: <b>ruta más corta</b> (cómo ir de A a B al menor costo), <b>árbol de expansión mínima</b> (cómo conectar todos los nodos con el menor largo total) y <b>flujo máximo</b> (cuánto puede pasar por la red como máximo).</p>",
  con:q9dl([["Nodo", "Punto de la red: bodega, cruce, faena, cliente."], ["Arco", "Conexión entre dos nodos, dirigida (un sentido) o no dirigida (doble sentido)."], ["Etiqueta (Dijkstra)", "Mejor distancia conocida desde el origen; se vuelve definitiva cuando el nodo se marca como visitado."], ["Árbol", "Red conectada sin ciclos; con n nodos tiene exactamente n − 1 arcos."], ["Kruskal", "Agrega los arcos de menor a mayor costo, saltando los que formarían un ciclo, hasta conectar todo."]]),
  fx:[["Actualización de Dijkstra", "d(v)=\\min\\{\\,d(v),\\ d(u)+w(u,v)\\,\\}", "d(v) = mín{ d(v) , d(u) + w(u,v) }", [["d(v)", "mejor distancia conocida al nodo v"], ["w(u,v)", "largo del arco u → v"]], "<p>Dijkstra siempre fija el nodo no visitado con menor etiqueta. Como todos los arcos son positivos, cualquier otro camino a ese nodo tendría que pasar por nodos con etiqueta igual o mayor y luego sumar más largo: no puede ser más corto. Por eso la etiqueta, una vez fijada, ya es la distancia mínima.</p>"],
      ["Largo de un árbol", "L=\\sum_{(u,v)\\in T} w(u,v),\\qquad |T|=n-1", "L = Σ w(u,v) en el árbol ;  arcos del árbol = n − 1", [["T", "conjunto de arcos elegidos"]], "<p>Kruskal es óptimo porque el arco más barato que cruza entre dos grupos aún no conectados siempre puede formar parte de algún árbol mínimo: si un árbol no lo usara, cambiarlo por el arco más caro del ciclo que se forma no lo empeoraría.</p>"]],
  met:q9ol(["<b>Dijkstra:</b> etiqueta el origen con 0 y el resto con ∞.", "Elige el nodo no visitado con menor etiqueta y márcalo como visitado.", "Para cada vecino, si d(nodo) + arco &lt; etiqueta del vecino, reemplázala y anota de dónde vino.", "Repite hasta visitar el destino; reconstruye la ruta hacia atrás con los «vino de».", "<b>Kruskal:</b> ordena los arcos de menor a mayor.", "Toma el siguiente arco: si une dos nodos que todavía no están conectados entre sí, agrégalo; si cierra un ciclo, descártalo.", "Detente al tener n − 1 arcos."]),
  ejB:["Camión de un packing al puerto de San Antonio (Dijkstra)", ilus + "<p>Kilómetros entre el packing (P), cuatro cruces (A, B, C, D) y el puerto (S): P–A 30, P–B 45, A–B 10, A–C 50, B–C 25, B–D 60, C–D 15, C–S 70, D–S 40 (doble sentido).</p>" +
    table(["Paso", "Nodo fijado", "Etiquetas actualizadas"], [["1", "P (0)", "A = 30, B = 45"], ["2", "A (30)", "B = mín(45, 30 + 10) = 40; C = 80"], ["3", "B (40)", "C = mín(80, 40 + 25) = 65; D = 100"], ["4", "C (65)", "D = mín(100, 65 + 15) = 80; S = 135"], ["5", "D (80)", "S = mín(135, 80 + 40) = 120"], ["6", "S (120)", "fin"]]) +
    "<p>Ruta: <b>P → A → B → C → D → S = 120 km</b> (30 + 10 + 25 + 15 + 40). Es más larga en número de tramos, pero más corta en kilómetros que P → B → C → S (140). Comprobado con la calculadora.</p>"],
  ejA:["Fibra óptica entre instalaciones de una faena minera (Kruskal)", ilus + "<p>Costo de tender fibra entre instalaciones (millones de $): Concentradora–Taller 3; Chancado–Concentradora 4; Laboratorio–Bodega 4; Concentradora–Laboratorio 5; Chancado–Taller 6; Taller–Campamento 7; Taller–Bodega 8; Chancado–Campamento 9; Campamento–Bodega 10; Laboratorio–Campamento 11.</p>" +
    table(["Arco (orden de costo)", "Costo", "Decisión"], [["Concentradora–Taller", "3", "Se agrega"], ["Chancado–Concentradora", "4", "Se agrega"], ["Laboratorio–Bodega", "4", "Se agrega"], ["Concentradora–Laboratorio", "5", "Se agrega (une los dos grupos)"], ["Chancado–Taller", "6", "Se descarta: cerraría un ciclo"], ["Taller–Campamento", "7", "Se agrega: ya hay 5 arcos = 6 − 1"]]) +
    "<p>Costo mínimo para conectar las 6 instalaciones: 3 + 4 + 4 + 5 + 7 = <b>23 millones</b>. Los arcos de 8, 9, 10 y 11 no se necesitan.</p><p><b>Ojo:</b> el árbol mínimo conecta todo al menor costo total, pero la ruta entre dos instalaciones puntuales dentro del árbol no tiene por qué ser la más corta (para eso es Dijkstra).</p>"],
  err:q9ul(["Aplicar Dijkstra con arcos negativos (no sirve; se usa Bellman-Ford).", "Fijar un nodo antes de que tenga la menor etiqueta.", "Confundir ruta más corta (de un origen a un destino) con árbol de expansión mínima (conectar todos).", "En Kruskal, agregar un arco que cierra un ciclo.", "Tratar como doble sentido una calle de un solo sentido."]),
  ejer:["<p>Red con arcos de doble sentido: O–A 4, O–B 2, A–B 1, A–C 5, B–C 8, B–D 10, C–D 2, C–T 6, D–T 3. Encuentra la ruta más corta de O a T.</p>", "Empieza en O. El primer nodo fijado es B (2). ¿Qué pasa con la etiqueta de A?", "A baja de 4 a 3 (pasando por B). Desde A, C = 8. Desde C, D = 10 y T = 14; desde D, T = 13.", "<p>Ruta <b>O → B → A → C → D → T = 13</b> (2 + 1 + 5 + 2 + 3). La alternativa O → B → A → C → T suma 14.</p>"],
  fic:["Dijkstra: fija el menor no visitado; arcos ≥ 0.", "Ruta: se reconstruye con «vino de».", "Kruskal: arcos de menor a mayor, sin ciclos, n − 1 arcos.", "Ruta más corta ≠ árbol mínimo."]
};

/* ---------------- PERT / CPM ---------------- */
T2["cpm"] = {
  def:"<p><b>CPM</b> (método de la ruta crítica) y <b>PERT</b> son técnicas para programar proyectos formados por actividades que dependen unas de otras. Calculan la <b>duración mínima</b> del proyecto, identifican la <b>ruta crítica</b> (las actividades que no pueden atrasarse sin atrasar todo) y la <b>holgura</b> de las demás. PERT agrega incertidumbre en las duraciones y permite estimar la probabilidad de terminar a tiempo.</p>",
  con:q9dl([["Precedencia", "Actividad que debe terminar antes de que empiece otra."], ["ES / EF", "Inicio y término más temprano."], ["LS / LF", "Inicio y término más tardío sin atrasar el proyecto."], ["Holgura total", "LS − ES: cuánto puede atrasarse una actividad sin atrasar el proyecto."], ["Ruta crítica", "Cadena de actividades con holgura 0; su largo es la duración del proyecto."], ["Tiempos PERT", "Optimista (a), más probable (m) y pesimista (b)."]]),
  fx:[["Pasadas hacia adelante y hacia atrás", "ES_j=\\max_{i\\to j} EF_i,\\quad EF_j=ES_j+t_j,\\quad LF_i=\\min_{i\\to j} LS_j,\\quad LS_i=LF_i-t_i", "ES_j = máx EF_i ;  EF_j = ES_j + t_j ;  LF_i = mín LS_j ;  LS_i = LF_i − t_i", [["t_j", "duración de la actividad j"]], "<p>Una actividad recién puede empezar cuando terminó la <b>última</b> de sus predecesoras (por eso el máximo). Hacia atrás, debe terminar antes de que tenga que empezar la <b>primera</b> de sus sucesoras (por eso el mínimo).</p>"],
      ["Duración esperada y varianza (PERT)", "t_e=\\frac{a+4m+b}{6},\\qquad \\sigma^2=\\left(\\frac{b-a}{6}\\right)^2", "t_e = (a + 4m + b) ÷ 6 ;  σ² = ((b − a) ÷ 6)²", [["a, m, b", "duración optimista, más probable y pesimista"]], "<p>PERT supone que cada duración sigue una distribución beta, cuya media se aproxima dando peso 4 al valor más probable. Se supone que entre a y b caben unas 6 desviaciones estándar, por eso σ = (b − a) ÷ 6.</p>"],
      ["Probabilidad de cumplir un plazo", "z=\\frac{T-T_e}{\\sqrt{\\sum_{\\text{crít}}\\sigma_i^2}},\\qquad P(\\text{terminar}\\le T)=\\Phi(z)", "z = (T − T_e) ÷ √(Σ σ² de la ruta crítica)", [["T_e", "duración esperada de la ruta crítica"], ["Φ", "distribución normal estándar acumulada"]], "<p>La duración del proyecto es la suma de las duraciones de la ruta crítica. Por el teorema central del límite, una suma de varias duraciones independientes se parece a una normal, con media igual a la suma de medias y varianza igual a la suma de varianzas.</p>"]],
  met:q9ol(["Lista actividades, duraciones y predecesoras.", "Pasada hacia adelante: ES = máximo EF de las predecesoras; EF = ES + t.", "Duración del proyecto = mayor EF.", "Pasada hacia atrás: LF = mínimo LS de las sucesoras (las finales con LF = duración); LS = LF − t.", "Holgura = LS − ES. Holgura 0 → crítica.", "Con PERT: calcula t_e y σ² de cada actividad, suma la varianza de la ruta crítica y obtén z y la probabilidad."]),
  ejB:["Instalación de una línea de envasado (CPM)", ilus + table(["Act.", "Descripción", "Duración (sem)", "Predecesoras"], [["A", "Ingeniería de detalle", "3", "—"], ["B", "Compra e importación de equipos", "5", "A"], ["C", "Obras civiles", "4", "A"], ["D", "Montaje", "3", "B, C"], ["E", "Capacitación de operadores", "2", "C"], ["F", "Puesta en marcha", "2", "D, E"]], { num:[2] }) +
    table(["Act.", "ES", "EF", "LS", "LF", "Holgura"], [["A", "0", "3", "0", "3", "0"], ["B", "3", "8", "3", "8", "0"], ["C", "3", "7", "4", "8", "1"], ["D", "8", "11", "8", "11", "0"], ["E", "7", "9", "9", "11", "2"], ["F", "11", "13", "11", "13", "0"]], { num:[1, 2, 3, 4, 5] }) +
    "<p>Duración: <b>13 semanas</b>. Ruta crítica: <b>A → B → D → F</b>. Las obras civiles pueden atrasarse 1 semana y la capacitación 2 sin mover la fecha final. D empieza en la semana 8 porque espera a B (EF = 8), aunque C ya terminó en la 7.</p>"],
  ejA:["Parada de planta en una faena minera (PERT)", ilus + table(["Act.", "Optimista (a)", "Más probable (m)", "Pesimista (b)", "Pred.", "Esperada (tₑ)", "Varianza (σ²)"], [["A", "2", "3", "6", "—", "3,33", "0,44"], ["B", "4", "6", "10", "A", "6,33", "1,00"], ["C", "3", "4", "5", "A", "4,00", "0,11"], ["D", "5", "7", "15", "B", "8,00", "2,78"], ["E", "2", "3", "4", "C", "3,00", "0,11"], ["F", "1", "2", "3", "D, E", "2,00", "0,11"]], { num:[1, 2, 3, 5, 6] }) +
    "<p>(Duraciones en días.) Ruta A → B → D → F: 3,33 + 6,33 + 8 + 2 = <b>19,67 días</b>. La otra ruta, A → C → E → F, suma 12,33. Varianza de la ruta crítica: 0,44 + 1 + 2,78 + 0,11 = 4,33 → σ = 2,08 días.</p>" +
    TX("P(T\\le 22)=\\Phi\\!\\left(\\frac{22-19{,}67}{2{,}08}\\right)=\\Phi(1{,}12)\\approx 0{,}869", "P(T ≤ 22) = Φ((22 − 19,67) ÷ 2,08) = Φ(1,12) ≈ 0,869", true) +
    "<p>Hay cerca de <b>87 %</b> de probabilidad de terminar en 22 días o menos, y solo 56 % de terminar en 20. Para tener 95 % de confianza se necesita un plazo de 19,67 + 1,645 × 2,08 ≈ <b>23,1 días</b>. La actividad D aporta la mayor varianza: reducir su incertidumbre es lo que más ayuda a cumplir.</p>"],
  err:q9ul(["Tomar el mínimo en la pasada hacia adelante (es el máximo).", "Calcular la probabilidad con la varianza de todas las actividades en vez de solo la ruta crítica.", "Sumar desviaciones estándar en vez de varianzas.", "Ignorar rutas casi críticas: si otra ruta tiene duración parecida y mucha varianza, la probabilidad real de atraso es mayor.", "Confundir holgura total con holgura libre."]),
  ejer:["<p>Actividades (días): A 2 (—), B 4 (A), C 3 (A), D 5 (B), E 2 (C), F 1 (D, E). Calcula la duración, la ruta crítica y las holguras.</p>", "Hacia adelante: B y C empiezan el día 2. D termina en 2 + 4 + 5 = 11. E termina en 2 + 3 + 2 = 7.", "F empieza en el máximo entre 11 y 7. Luego haz la pasada hacia atrás desde la duración total.", "<p>Duración <b>12 días</b>; ruta crítica <b>A → B → D → F</b>; holguras: C = 4 y E = 4; las demás 0.</p>"],
  fic:["Adelante: máximo; atrás: mínimo.", "Holgura = LS − ES; 0 = crítica.", "PERT: t_e = (a + 4m + b) ÷ 6 ;  σ = (b − a) ÷ 6.", "Se suman varianzas de la ruta crítica.", "z = (T − T_e) ÷ σ_ruta."]
};

/* ---------------- COLAS ---------------- */
T2["colas"] = {
  def:"<p>La <b>teoría de colas</b> estudia sistemas donde llegan clientes (personas, camiones, llamadas, órdenes) a recibir un servicio. Permite calcular cuánto esperan, cuántos hay en la fila y qué tan ocupados están los servidores, para decidir <b>cuántos servidores</b> poner. La notación M/M/c significa llegadas de Poisson (M), tiempos de servicio exponenciales (M) y c servidores en paralelo con una sola fila.</p>",
  con:q9dl([["λ (lambda)", "Tasa de llegada: clientes por unidad de tiempo."], ["μ (mu)", "Tasa de servicio de un servidor: clientes que atiende por unidad de tiempo (1 ÷ tiempo medio de atención)."], ["ρ (rho)", "Utilización: fracción del tiempo que los servidores están ocupados. Debe ser menor que 1."], ["L, Lq", "Clientes promedio en el sistema y en la cola."], ["W, Wq", "Tiempo promedio en el sistema y esperando en la cola."], ["Ley de Little", "L = λ·W: vale para casi cualquier sistema estable."]]),
  fx:[["M/M/1", "\\rho=\\frac{\\lambda}{\\mu},\\quad L=\\frac{\\rho}{1-\\rho},\\quad W_q=\\frac{\\lambda}{\\mu(\\mu-\\lambda)},\\quad W=\\frac{1}{\\mu-\\lambda}", "ρ = λ ÷ μ ;  L = ρ ÷ (1 − ρ) ;  Wq = λ ÷ (μ·(μ − λ)) ;  W = 1 ÷ (μ − λ)", [["λ, μ", "en la misma unidad de tiempo"]], "<p>Con llegadas y servicios aleatorios, la probabilidad de que haya n clientes es (1 − ρ)·ρⁿ: cada cliente adicional es ρ veces menos probable. Sumando n·P(n) se obtiene L = ρ ÷ (1 − ρ). Cuando ρ se acerca a 1 el denominador tiende a 0 y la cola explota: con ρ = 0,8 hay 4 clientes en promedio; con ρ = 0,95, 19.</p>"],
      ["M/M/c (fórmula de Erlang C)", "P_0=\\left[\\sum_{n=0}^{c-1}\\frac{a^n}{n!}+\\frac{a^c}{c!(1-\\rho)}\\right]^{-1},\\quad L_q=\\frac{P_0\\,a^c\\,\\rho}{c!\\,(1-\\rho)^2},\\quad a=\\frac{\\lambda}{\\mu},\\ \\rho=\\frac{a}{c}", "P₀ = 1 ÷ [Σ aⁿ ÷ n! + a^c ÷ (c!·(1 − ρ))] ;  Lq = P₀·a^c·ρ ÷ (c!·(1 − ρ)²)", [["a", "carga ofrecida (servidores ocupados en promedio)"], ["c", "número de servidores"]], "<p>Mientras haya menos de c clientes, todos se atienden sin esperar; desde c en adelante, el sistema se comporta como una fila que avanza a velocidad c·μ. Sumando ambas partes y normalizando para que las probabilidades sumen 1 se obtiene P₀; con ella se calcula Lq, y luego Wq = Lq ÷ λ, W = Wq + 1 ÷ μ y L = λ·W.</p>"]],
  met:q9ol(["Define la unidad de tiempo y calcula λ y μ en esa unidad (μ = 60 ÷ minutos de atención, si es por hora).", "Verifica estabilidad: ρ = λ ÷ (c·μ) &lt; 1.", "Calcula Lq y Wq con la fórmula del modelo (M/M/1 o M/M/c).", "Completa con W = Wq + 1 ÷ μ y L = λ·W (ley de Little).", "Si hay costos: costo total por hora = c × costo del servidor + L (o Lq) × costo de espera por cliente-hora.", "Repite con c = 1, 2, 3, … y elige el menor costo total."]),
  ejB:["Caja de un minimarket (M/M/1)", ilus + "<p>Llegan 20 clientes por hora y la cajera atiende 25 por hora (2,4 minutos cada uno).</p>" + table(["Medida", "Cálculo", "Resultado"], [["Utilización", "20 ÷ 25", "0,80 (80 %)"], ["Clientes en el sistema", "0,8 ÷ 0,2", "4"], ["Clientes en cola", "0,8² ÷ 0,2", "3,2"], ["Tiempo en el sistema", "1 ÷ (25 − 20) h", "12 min"], ["Espera en la fila", "20 ÷ (25 × 5) h", "9,6 min"]]) +
    "<p>Comprobación con Little: L = λ·W = 20 × 0,2 h = 4 ✓. La probabilidad de encontrar 3 o más personas es ρ³ = 0,512: la mitad de las veces el cliente ve una fila de 3 o más. Comprobado con la calculadora.</p>"],
  ejA:["Andenes de descarga en un centro de distribución de retail (M/M/c con costos)", ilus + "<p>Llegan 6 camiones por hora; un andén descarga 2,5 camiones por hora (24 min cada uno). Cada andén operativo cuesta $18.000 por hora (cuadrilla y equipo) y cada hora que un camión pasa en el CD cuesta $30.000 (camión y chofer detenidos).</p>" +
    table(["Andenes c", "ρ", "Lq", "Wq", "L", "Costo total por hora"], [["2", "1,20", "—", "inestable", "—", "—"], ["3", "0,80", "2,59", "25,9 min", "4,99", "$203.663"], ["4", "0,60", "0,43", "4,3 min", "2,83", "<b>$156.917</b>"], ["5", "0,48", "0,10", "1,0 min", "2,50", "$165.143"]], { num:[0, 1, 2, 4, 5] }) +
    "<p>Costo total = c × 18.000 + L × 30.000. Con 2 andenes la fila crece sin límite (ρ &gt; 1). <b>La mejor decisión son 4 andenes</b>: pasar de 3 a 4 baja la espera de 26 a 4 minutos y ahorra casi $47.000 por hora; un quinto andén ya cuesta más de lo que ahorra. Con c = 3, la probabilidad de que un camión tenga que esperar es 65 %; con c = 4 baja a 29 %. Comprobado con la calculadora para c = 3, 4 y 5.</p>"],
  err:q9ul(["Usar λ y μ en unidades distintas (por hora y por minuto).", "Usar μ como tiempo de atención (es la tasa: 1 ÷ tiempo).", "Aplicar las fórmulas con ρ ≥ 1: el sistema no es estable y la fila crece sin fin.", "Pensar que con ρ = 0,9 «sobra un 10 %»: la espera ya es muy alta.", "Aplicar M/M/c cuando cada servidor tiene su propia fila (es parecido a c sistemas M/M/1, que funcionan peor)."]),
  ejer:["<p>A una ventanilla de un servicio público llegan 12 personas por hora; el funcionario atiende 15 por hora. ¿Cuánto espera una persona en la fila y cuántas hay en promedio en el sistema?</p>", "Calcula ρ = λ ÷ μ y verifica que sea menor que 1.", "Wq = λ ÷ (μ·(μ − λ)) en horas; multiplica por 60. L = ρ ÷ (1 − ρ).", "<p>ρ = 0,8; Wq = 12 ÷ (15 × 3) = 0,267 h = <b>16 minutos</b>; L = <b>4 personas</b>; W = 1 ÷ 3 h = 20 minutos.</p>"],
  fic:["ρ = λ ÷ (c·μ) &lt; 1 siempre.", "M/M/1: L = ρ ÷ (1 − ρ); W = 1 ÷ (μ − λ).", "Little: L = λ·W; Lq = λ·Wq.", "La espera crece muy rápido cuando ρ pasa de 0,8.", "Número óptimo de servidores: mínimo de costo de servicio + costo de espera."]
};

/* ---------------- SIMULACIÓN MONTECARLO ---------------- */
T2["simulacion-mc"] = {
  def:"<p>La <b>simulación de Montecarlo</b> imita muchas veces un sistema con incertidumbre usando números aleatorios, para estimar resultados (costos, faltantes, plazos) cuando las fórmulas son difíciles o no existen. En vez de resolver el modelo, se «juega» día por día con datos que siguen la misma distribución que la realidad.</p>",
  con:q9dl([["Variable aleatoria", "Dato incierto: demanda diaria, tiempo de atención, falla."], ["Distribución", "Probabilidad de cada valor. Puede venir de datos históricos (frecuencia relativa)."], ["Número aleatorio", "Número entre 00 y 99 (o entre 0 y 1) en que todos los valores son igualmente probables."], ["Rango de asignación", "Intervalo de números aleatorios que representa cada valor, proporcional a su probabilidad."], ["Réplica", "Una corrida completa de la simulación; se repite muchas veces para reducir el error."], ["Números comunes", "Usar los mismos números aleatorios para comparar dos políticas, para que la diferencia se deba a la política y no al azar."]]),
  fx:[["Asignación de números aleatorios", "x=x_k\\ \\text{si}\\ F(x_{k-1})\\le U<F(x_k)", "x = x_k  si  F(x_{k−1}) ≤ U < F(x_k)", [["U", "número aleatorio uniforme entre 0 y 1"], ["F", "probabilidad acumulada"]], "<p>Si el valor x_k tiene probabilidad 0,40, se le asigna un tramo de largo 0,40 dentro de [0, 1). Como U cae en cualquier punto con igual probabilidad, cae en ese tramo el 40 % de las veces: el valor simulado aparece con la frecuencia correcta.</p>"],
      ["Error de la estimación", "\\bar{x}\\pm z\\,\\frac{s}{\\sqrt{n}}", "x̄ ± z·s ÷ √n", [["n", "número de réplicas"], ["s", "desviación estándar de los resultados"]], "<p>Cada réplica es una muestra del resultado. El promedio de n réplicas tiene un error que cae con √n: para reducir el error a la mitad se necesitan 4 veces más réplicas.</p>"]],
  met:q9ol(["Define qué quieres estimar (costo promedio, faltantes) y la regla de decisión que pruebas.", "Construye la distribución de cada variable incierta y su probabilidad acumulada.", "Asigna rangos de números aleatorios (00–99) proporcionales a cada probabilidad.", "Para cada período: toma un número aleatorio, convierte a valor, aplica las reglas y anota resultados.", "Calcula los indicadores (promedios, totales).", "Repite muchas réplicas (cientos o miles en computador) y entrega el promedio con su intervalo.", "Para comparar políticas, usa los mismos números aleatorios."]),
  ejB:["Demanda diaria de un repuesto", ilus + table(["Demanda", "Probabilidad", "Acumulada", "Números aleatorios"], [["0", "0,10", "0,10", "00–09"], ["1", "0,20", "0,30", "10–29"], ["2", "0,40", "0,70", "30–69"], ["3", "0,20", "0,90", "70–89"], ["4", "0,10", "1,00", "90–99"]], { num:[0, 1, 2] }) +
    "<p>Con los números 27, 81, 05, 63, 94, 42, 18, 70, 56 y 39 se obtienen las demandas 1, 3, 0, 2, 4, 2, 1, 3, 2 y 2. Promedio simulado: 20 ÷ 10 = <b>2,0</b> unidades por día. El valor esperado teórico es 0·0,1 + 1·0,2 + 2·0,4 + 3·0,2 + 4·0,1 = 2,0: coinciden (con solo 10 días podrían haber diferido).</p>"],
  ejA:["Comparar dos puntos de pedido con números comunes", ilus + "<p>Mismo repuesto, stock inicial 6. Al final de cada día, si el stock es menor o igual al punto de pedido s y no hay un pedido en camino, se piden 6 unidades, que llegan al inicio del segundo día siguiente. La demanda que no se cubre se pierde. Costos: $15.000 por pedido, $500 por unidad en stock al cierre de cada día y $4.000 por unidad faltante. Se simulan 15 días con los números 27, 81, 05, 63, 94, 42, 18, 70, 56, 39, 88, 12, 76, 33 y 51.</p>" +
    table(["Día", "Llega", "Stock inicial", "N.° aleatorio", "Demanda", "Faltante", "Stock final", "Pedido (s = 3)"], [["1", "", "6", "27", "1", "0", "5", ""], ["2", "", "5", "81", "3", "0", "2", "sí, llega día 4"], ["3", "", "2", "05", "0", "0", "2", ""], ["4", "6", "8", "63", "2", "0", "6", ""], ["5", "", "6", "94", "4", "0", "2", "sí, llega día 7"], ["6", "", "2", "42", "2", "0", "0", ""], ["7", "6", "6", "18", "1", "0", "5", ""], ["8", "", "5", "70", "3", "0", "2", "sí, llega día 10"], ["9", "", "2", "56", "2", "0", "0", ""], ["10", "6", "6", "39", "2", "0", "4", ""], ["11", "", "4", "88", "3", "0", "1", "sí, llega día 13"], ["12", "", "1", "12", "1", "0", "0", ""], ["13", "6", "6", "76", "3", "0", "3", "sí, llega día 15"], ["14", "", "3", "33", "2", "0", "1", ""], ["15", "6", "7", "51", "2", "0", "5", ""]], { num:[0, 1, 2, 3, 4, 5, 6] }) +
    table(["Política", "Pedidos", "Faltantes", "Suma de stocks finales", "Costo total"], [["s = 3", "5", "0", "38", "<b>$94.000</b>"], ["s = 2", "5", "1", "33", "$95.500"]], { num:[1, 2, 3, 4] }) +
    "<p>Con s = 2 se ahorra un poco en mantener inventario ($2.500), pero aparece 1 faltante ($4.000). En estos 15 días gana s = 3 por $1.500. <b>Conclusión prudente:</b> la diferencia es pequeña y se basa en una sola réplica de 15 días; antes de decidir hay que repetir cientos de réplicas (por ejemplo, con la calculadora de Montecarlo o en Excel) y comparar promedios con su intervalo.</p>"],
  err:q9ul(["Asignar rangos que no son proporcionales a las probabilidades (por ejemplo, 00–10 para 10 %, que son 11 números).", "Sacar conclusiones con una sola réplica o muy pocos períodos.", "Comparar políticas con números aleatorios distintos: el azar se confunde con la diferencia real.", "No validar: el modelo debe reproducir los datos históricos antes de usarse para decidir.", "Olvidar el período de calentamiento cuando el estado inicial no es representativo."]),
  ejer:["<p>Con la distribución de demanda del ejemplo básico, simula 5 días con los números aleatorios 64, 09, 91, 35 y 72. ¿Cuál es la demanda promedio simulada?</p>", "Ubica cada número en su rango: 00–09 → 0; 10–29 → 1; 30–69 → 2; 70–89 → 3; 90–99 → 4.", "64 → 2; 09 → 0. Sigue con 91, 35 y 72.", "<p>Demandas: 2, 0, 4, 2 y 3. Promedio = 11 ÷ 5 = <b>2,2</b>. Difiere del esperado (2,0) porque 5 días son muy pocos: es exactamente el error de muestreo que se reduce con más réplicas.</p>"],
  fic:["Rangos de números aleatorios proporcionales a la probabilidad.", "Una réplica no basta: promedia muchas.", "Error ∝ 1 ÷ √n.", "Compara políticas con números comunes.", "Valida el modelo con datos reales."]
};

/* ---------------- INVENTARIOS: EOQ, EPQ Y PUNTO DE REORDEN ---------------- */
T2["eoq"] = {
  def:"<p>Los <b>modelos de inventario</b> responden dos preguntas: <b>cuánto pedir</b> y <b>cuándo pedir</b>. El <b>EOQ</b> (lote económico de pedido) encuentra la cantidad que minimiza la suma del costo de pedir y el de mantener inventario cuando la demanda es constante. El <b>EPQ</b> es su versión para cuando el lote se fabrica gradualmente en vez de llegar de una vez. El <b>punto de reorden</b> indica con qué nivel de stock emitir el pedido.</p>",
  con:q9dl([["Costo de pedir (S)", "Costo fijo de cada pedido o puesta en marcha: emisión, transporte, recepción, preparación de máquina."], ["Costo de mantener (H)", "Costo de tener una unidad un año: capital inmovilizado, bodega, seguros, mermas. Suele expresarse como % del costo unitario (H = i·C)."], ["Ciclo", "Tiempo entre dos pedidos: Q ÷ D."], ["Tiempo de entrega (L)", "Días entre emitir el pedido y recibirlo."], ["Punto de reorden (ROP)", "Stock con el que se emite el pedido para que llegue justo cuando se agota."], ["Descuento por cantidad", "Precio menor si se compra sobre cierta cantidad; cambia el costo total y puede convenir pedir más que el EOQ."]]),
  fx:[["Costo total anual", "CT(Q)=\\frac{D}{Q}S+\\frac{Q}{2}H\\ (+\\,D\\,C)", "CT = (D ÷ Q)·S + (Q ÷ 2)·H  (+ D·C)", [["D", "demanda anual"], ["Q", "unidades por pedido"]], "<p>Al año se hacen D ÷ Q pedidos, cada uno cuesta S. El inventario baja en forma pareja desde Q hasta 0, así que el promedio en bodega es Q ÷ 2, y cada unidad promedio cuesta H al año.</p>"],
      ["Lote económico (EOQ)", "Q^{*}=\\sqrt{\\frac{2DS}{H}}", "Q* = √(2·D·S ÷ H)", [["Q*", "cantidad que minimiza CT"]], "<p>El costo de pedir baja al aumentar Q y el de mantener sube. Derivando CT e igualando a cero: −DS ÷ Q² + H ÷ 2 = 0, de donde Q² = 2DS ÷ H. En ese punto ambos costos son iguales. La curva es muy plana cerca del óptimo: pedir 20 % más sube el costo cerca de 1,7 %, y 20 % menos, cerca de 2,5 %.</p>"],
      ["Lote económico de producción (EPQ)", "Q^{*}=\\sqrt{\\frac{2DS}{H\\,(1-D/p)}},\\qquad I_{\\max}=Q^{*}\\left(1-\\frac{D}{p}\\right)", "Q* = √(2·D·S ÷ (H·(1 − D ÷ p))) ;  I_máx = Q*·(1 − D ÷ p)", [["p", "tasa de producción anual (mayor que D)"]], "<p>Mientras se produce, el stock sube a velocidad p − D (se fabrica y a la vez se consume), así que nunca llega a Q: el máximo es Q·(1 − D ÷ p). El costo de mantener es menor que en el EOQ, por eso conviene un lote más grande.</p>"],
      ["Punto de reorden", "ROP=d\\cdot L\\ (+\\,SS)", "ROP = d·L  (+ SS)", [["d", "demanda diaria"], ["L", "tiempo de entrega en días"], ["SS", "stock de seguridad (ver la calculadora de stock de seguridad)"]], "<p>Durante los L días que tarda el pedido se consumen d·L unidades. Si se pide cuando quedan exactamente esas unidades, el pedido llega justo al agotarse. El stock de seguridad cubre la variación de la demanda y del plazo.</p>"]],
  met:q9ol(["Reúne D (anual), S (por pedido), C (costo unitario) e i (% anual de mantener); calcula H = i·C.", "Calcula Q* = √(2DS ÷ H) y redondea a un lote práctico (cajas, pallets).", "Calcula N = D ÷ Q* pedidos al año y el ciclo en días.", "Calcula el costo total y compáralo con la política actual.", "Si hay producción gradual, usa EPQ con el factor (1 − D ÷ p).", "Si hay descuentos: para cada tramo de precio calcula el EOQ con su H; si queda bajo el mínimo del tramo, súbelo al mínimo; compara el costo total incluyendo la compra (D·C) y elige el menor.", "Fija el punto de reorden: ROP = d·L + SS."]),
  ejB:["Distribuidora de alimentos en Temuco (EOQ y punto de reorden)", ilus + "<p>Demanda: 4.800 cajas al año (300 días hábiles). Pedir cuesta $25.000; cada caja cuesta $2.000 y mantenerla un año cuesta 25 % de su valor. El proveedor demora 5 días.</p>" +
    q9ol(["H = 0,25 × 2.000 = $500 por caja al año.", "Q* = √(2 × 4.800 × 25.000 ÷ 500) = √480.000 = <b>692,8 ≈ 693 cajas</b>.", "Pedidos al año: 4.800 ÷ 693 ≈ 6,9; un pedido cada 43 días hábiles.", "Costo anual de pedir + mantener: 6,93 × 25.000 + 346,5 × 500 ≈ <b>$346.410</b> (mitad pedir, mitad mantener).", "Demanda diaria d = 4.800 ÷ 300 = 16 cajas; ROP = 16 × 5 = <b>80 cajas</b>."]) +
    table(["Lote Q", "Costo pedir + mantener"], [["500", "$365.000"], ["693", "<b>$346.410</b>"], ["900", "$358.333"]], { num:[0, 1] }) +
    "<p>La tabla muestra lo plana que es la curva: pedir 900 en vez de 693 cuesta solo 3,4 % más. Comprobado con la calculadora.</p>"],
  ejA:[["Planta de bebidas: lote de producción (EPQ)", ilus + "<p>Una línea embotella un sabor con demanda de 60.000 unidades al año y puede producir a un ritmo de 300.000 por año. Cada cambio de formato cuesta $400.000 y mantener una unidad un año cuesta $120. Año de 250 días de operación.</p>" +
      q9ol(["1 − D ÷ p = 1 − 60.000 ÷ 300.000 = 0,8.", "Q* = √(2 × 60.000 × 400.000 ÷ (120 × 0,8)) = √500.000.000 = <b>22.361 unidades</b> por corrida.", "Inventario máximo = 22.361 × 0,8 = 17.889 (nunca se llega a 22.361 porque se vende mientras se produce).", "Duración de cada corrida: 22.361 ÷ 300.000 × 250 = 18,6 días; ciclo completo: 22.361 ÷ 60.000 × 250 = 93,2 días; unas 2,7 corridas al año.", "Costo anual de cambios + mantener: <b>$2.146.625</b>. Si se usara la fórmula EOQ simple (20.000 unidades) el costo sería $2.160.000."]) +
      "<p>El EPQ recomienda lotes más grandes que el EOQ porque el inventario promedio es menor para el mismo lote. <b>En la calculadora</b> la tasa de producción se ingresa por día: 300.000 ÷ 250 = 1.200 unidades/día (y H = $120 se obtiene, por ejemplo, con costo unitario $480 e i = 25 %). Comprobado: entrega 22.361 unidades y $2.146.625.</p>"],
    ["Descuento por cantidad", ilus + "<p>Volviendo a la distribuidora de Temuco: el proveedor ofrece la caja a $1.900 si se compran 1.000 o más por pedido.</p>" +
      table(["Tramo", "H = 25 % del precio", "EOQ del tramo", "Q a usar", "Costo total anual (incluye compra)"], [["$2.000 (menos de 1.000)", "$500", "693", "693", "$9.946.410"], ["$1.900 (1.000 o más)", "$475", "711 (bajo el mínimo)", "1.000", "<b>$9.477.500</b>"]], { num:[1, 2, 3, 4] }) +
      "<p>Con el descuento: compra 4.800 × 1.900 = 9.120.000; pedir 4,8 × 25.000 = 120.000; mantener 500 × 475 = 237.500. <b>Conviene pedir 1.000 cajas</b>: se ahorran $468.910 al año, aunque se mantenga más inventario.</p>"]],
  err:q9ul(["Usar D mensual con H anual (o al revés).", "Usar H como el precio del producto: es el costo de mantenerlo, normalmente 15 % a 35 % anual del precio (verificar con los datos de cada empresa).", "Olvidar el costo de compra al evaluar descuentos.", "Pensar que el EOQ es exacto: los datos de S y H son estimaciones; por suerte la curva es plana.", "Calcular el punto de reorden sin stock de seguridad cuando la demanda o el plazo varían.", "Aplicar EOQ a demanda muy estacional o a productos perecibles sin ajustar."]),
  ejer:["<p>Una ferretería vende 9.000 unidades al año de un producto (300 días hábiles). Pedir cuesta $20.000 y mantener una unidad un año cuesta $250. El proveedor demora 4 días. Calcula el lote económico y el punto de reorden.</p>", "Reemplaza en Q* = √(2·D·S ÷ H): 2 × 9.000 × 20.000 = 360.000.000.", "Para el punto de reorden: d = 9.000 ÷ 300 por día; multiplícalo por L.", "<p>Q* = √(360.000.000 ÷ 250) = √1.440.000 = <b>1.200 unidades</b> (7,5 pedidos al año). d = 30 por día; ROP = 30 × 4 = <b>120 unidades</b>.</p>"],
  fic:["Q* = √(2DS ÷ H): iguala costo de pedir y de mantener.", "EPQ: divide H por (1 − D ÷ p) → lote mayor.", "ROP = d·L + SS.", "Descuentos: compara costo total incluyendo la compra.", "Curva plana: redondear a cajas o pallets casi no cambia el costo."]
};

/* ---------------- STOCK DE SEGURIDAD ---------------- */
T2["stock-seguridad"] = {
  def:"<p>El <b>stock de seguridad</b> (SS) es inventario adicional que se mantiene para no quedar sin stock cuando la demanda o el tiempo de entrega resultan mayores que lo esperado. Su tamaño depende de cuánta variación hay y de qué <b>nivel de servicio</b> se quiere: la probabilidad de no tener quiebre durante un ciclo de reposición.</p>",
  con:q9dl([["Nivel de servicio (NS)", "Probabilidad de no quebrar stock en un ciclo. 95 % significa quebrar en promedio 1 de cada 20 ciclos."], ["Factor z", "Número de desviaciones estándar de la normal que corresponde al NS: 90 % → 1,28; 95 % → 1,645; 97,5 % → 1,96; 99 % → 2,33."], ["σ_d", "Desviación estándar de la demanda diaria."], ["σ_L", "Desviación estándar del tiempo de entrega (días)."], ["Revisión continua (Q)", "Se revisa siempre y se pide al llegar al ROP; el riesgo cubre solo el plazo L."], ["Revisión periódica (P)", "Se revisa cada T días; el riesgo cubre T + L, por lo que necesita más stock de seguridad."]]),
  fx:[["Demanda variable, plazo fijo", "SS=z\\,\\sigma_d\\sqrt{L}", "SS = z·σ_d·√L", [["L", "tiempo de entrega en días"]], "<p>La demanda de L días es la suma de L demandas diarias independientes. Al sumar variables independientes se suman sus varianzas: L·σ_d², cuya raíz es σ_d·√L. Por eso el riesgo no crece en proporción a L, sino a su raíz.</p>"],
      ["Demanda y plazo variables", "SS=z\\sqrt{L\\,\\sigma_d^2+\\bar{d}^{\\,2}\\,\\sigma_L^2}", "SS = z·√(L·σ_d² + d̄²·σ_L²)", [["d̄", "demanda diaria promedio"]], "<p>Hay dos fuentes de incertidumbre: cuánto se vende por día (L·σ_d²) y cuántos días tarda el pedido; cada día extra de atraso consume d̄ unidades más, lo que aporta d̄²·σ_L². Las varianzas independientes se suman.</p>"],
      ["Punto de reorden", "ROP=\\bar{d}\\,L+SS", "ROP = d̄·L + SS", [["d̄·L", "consumo esperado durante el plazo"]], "<p>Se pide cuando el stock alcanza lo que se espera consumir mientras llega el pedido, más un colchón para los casos en que se consume más.</p>"]],
  met:q9ol(["Obtén d̄ y σ_d de los datos de demanda diaria (o semanal, y conviértelos a la unidad del plazo).", "Obtén L y, si varía, σ_L del historial del proveedor.", "Elige el nivel de servicio según el costo de quebrar y busca z.", "Calcula σ durante el plazo con la fórmula que corresponda.", "SS = z·σ; redondea hacia arriba.", "ROP = d̄·L + SS (en revisión periódica usa T + L en vez de L).", "Evalúa el costo: SS × H al año, y compáralo con el costo de los quiebres que evita."]),
  ejB:["Repuesto de alta rotación en una bodega de mantención", ilus + "<p>Demanda: 40 unidades diarias en promedio, con σ_d = 8. El proveedor local entrega siempre en 4 días. Nivel de servicio deseado: 95 % (z = 1,645).</p>" +
    q9ol(["σ durante el plazo = 8 × √4 = 16 unidades.", "SS = 1,645 × 16 = 26,3 → <b>27 unidades</b>.", "ROP = 40 × 4 + 27 = <b>187 unidades</b>."]) + "<p>Comprobado con la calculadora.</p>"],
  ejA:["Insumo importado por el puerto de San Antonio (plazo variable)", ilus + "<p>Una planta consume en promedio 120 unidades diarias de un insumo importado (σ_d = 30). El tiempo total de entrega (fabricación, viaje marítimo, puerto y aduana) promedia 20 días, con σ_L = 4 días.</p>" +
    q9ol(["Aporte de la demanda: L·σ_d² = 20 × 30² = 18.000.", "Aporte del plazo: d̄²·σ_L² = 120² × 4² = 230.400.", "σ = √(18.000 + 230.400) = √248.400 = 498,4 unidades.", "Con 95 %: SS = 1,645 × 498,4 = <b>820 unidades</b>; ROP = 120 × 20 + 820 = <b>3.220 unidades</b>.", "Con 99 %: SS = 2,326 × 498,4 = 1.159,4 → 1.160 unidades (340 más)."]) +
    "<p><b>Lectura:</b> si se ignorara la variación del plazo, el SS sería solo 1,645 × 30 × √20 = 221 unidades. El 93 % de la varianza viene del plazo de importación, no de la demanda: negociar un plazo más confiable o tener un proveedor local de respaldo reduce más inventario que mejorar el pronóstico.</p>"],
  err:q9ul(["Usar σ semanal con L en días (todas las cifras en la misma unidad de tiempo).", "Sumar desviaciones estándar en vez de varianzas.", "Confundir el nivel de servicio por ciclo con la tasa de llenado (% de unidades entregadas): no son lo mismo.", "Usar z = 1,96 para 95 %: ese valor es para 95 % de dos colas; para stock (una cola) es 1,645.", "Fijar 99,9 % para todos los productos: el costo de inventario crece muy rápido; segmenta con ABC."]),
  ejer:["<p>Demanda diaria promedio 50 unidades (σ_d = 10); plazo fijo de 9 días; nivel de servicio 97,5 % (z = 1,96). Calcula SS y ROP.</p>", "σ durante el plazo = σ_d·√L = 10 × √9.", "SS = 1,96 × 30. El ROP suma el consumo esperado del plazo, 50 × 9.", "<p>σ = 30; SS = 58,8 → <b>59 unidades</b>; ROP = 450 + 59 = <b>509 unidades</b>.</p>"],
  fic:["SS = z·σ durante el plazo.", "Se suman varianzas: L·σ_d² + d̄²·σ_L².", "95 % → z = 1,645 (una cola).", "ROP = d̄·L + SS.", "Plazos variables suelen pesar más que la demanda."]
};

/* ---------- Bloques nuevos como secciones desplegables ---------- */
function t2Blocks(id){
  const x = T2[id]; if (!x) return null; const B = {}, pre = x.tema ? x.tema + " · " : "";
  const mk = (t, h, open) => { const d = document.createElement("details"); d.className = "item t2"; if (open) d.open = true; d.innerHTML = "<summary>" + pre + t + '</summary><div class="body prose">' + h + "</div>"; return d; };
  if (x.def) B.def = [mk("Definición", x.def)];
  if (x.con) B.con = [mk("Conceptos clave", x.con)];
  const fv = n => esc(n).replace(/_\(?([A-Za-z0-9áéíóú,−\-]+)\)?/g, "<sub>$1</sub>").replace(/\^([0-9*]+)/g, "<sup>$1</sup>");
  if (x.fx && x.fx.length) B.fx = [mk("Fórmulas clave y por qué funcionan", x.fx.map(f => UI.formula(f[0], f[1], f[2], (f[3] || []).map(v => [fv(v[0]), v[1]]), f[4])).join(""))];
  if (x.met) B.met = [mk("Método paso a paso", x.met)];
  if (x.ejB) B.ej = [mk("Ejemplo básico: " + x.ejB[0], x.ejB[1])].concat((!x.ejA ? [] : Array.isArray(x.ejA[0]) ? x.ejA : [x.ejA]).map(e => mk("Ejemplo avanzado: " + e[0], e[1])));
  if (x.err) B.err = [mk("Errores comunes", x.err)];
  if (x.ejer) B.ejer = [mk("Ejercicio con pistas", UI.ejercicio(x.ejer[0], [x.ejer[1], x.ejer[2]], x.ejer[3]))];
  if (x.fic) B.fic = [mk("Ficha resumen", UI.ficha(x.fic))];
  return B; }
